From a5a2c1b9670c0d4dc0d9d354e8883d96ca206f4e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 28 Nov 2026 13:17:31 +0100
Subject: [PATCH] AppletPopup: don't save the size of a popup that was never
 shown

Qt also sends hide events to popups that were never shown, so a newly
added applet saved whatever size its unshown popup had, and after a
restart its popup opened at that size. Only save the size once shown.

BUG: 488937
---
 src/plasmaquick/appletpopup.cpp | 12 ++++++++++--
 src/plasmaquick/appletpopup.h   |  2 ++
 2 files changed, 12 insertions(+), 2 deletions(-)

diff --git a/src/plasmaquick/appletpopup.cpp b/src/plasmaquick/appletpopup.cpp
index edb9c6885..0db5f97c9 100644
--- a/src/plasmaquick/appletpopup.cpp
+++ b/src/plasmaquick/appletpopup.cpp
@@ -135,10 +135,18 @@ void AppletPopup::setAppletInterface(QQuickItem *appletInterface)
     Q_EMIT appletInterfaceChanged();
 }

+void AppletPopup::showEvent(QShowEvent *event)
+{
+    m_shown = true;
+    PopupPlasmaWindow::showEvent(event);
+}
+
 void AppletPopup::hideEvent(QHideEvent *event)
 {
-    // Persist the size if this contains an applet
-    if (m_appletInterface) {
+    // Persist the size if this contains an applet. Qt also sends hide events to
+    // a popup that was never shown, whose size isn't one anybody saw
+    const bool wasShown = std::exchange(m_shown, false);
+    if (m_appletInterface && wasShown) {
         KConfigGroup config = m_appletInterface->applet()->config();
         // save size without margins, so we're robust against theme changes
         const QSize popupSize = size().shrunkBy(padding());
diff --git a/src/plasmaquick/appletpopup.h b/src/plasmaquick/appletpopup.h
index 2b7c5888b..1b86efcd1 100644
--- a/src/plasmaquick/appletpopup.h
+++ b/src/plasmaquick/appletpopup.h
@@ -49,6 +49,7 @@ Q_SIGNALS:
     void appletInterfaceChanged();

 protected:
+    void showEvent(QShowEvent *event) override;
     void hideEvent(QHideEvent *event) override;

 private:
@@ -60,6 +61,7 @@ private:
     QPointer<AppletQuickItem> m_appletInterface;
     QPointer<QScreen> m_oldScreen;
     bool m_sizeExplicitlySetFromConfig = false;
+    bool m_shown = false;
     QScopedPointer<LayoutChangedProxy> m_layoutChangedProxy;
 };

-- 
2.53.0

